import { act, renderHook, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import type { ModelInfo, RecordEnvelope, RecordsPage } from '../../../types/dto';
import { useDbInspector } from './use-db-inspector';

const { invokeMock } = vi.hoisted(() => ({
  invokeMock: vi.fn(),
}));

vi.mock('@tauri-apps/api/core', () => ({
  invoke: invokeMock,
}));

// ---------------------------------------------------------------------------
// useDbInspector 取数收口单测：IPC 边界（@tauri-apps/api/core）以 invoke 替身
// 按命令名分发固定 fixture 并记录调用序列（沿 use-workspaces.test.ts 替身模式）。
// 查询轨无 toast：hook 不引 sonner（错误 inline 由视图承载），不 mock sonner。
// 页长 50 与 hook 内 PAGE_SIZE 常量同源（未导出，按实现值字面书写）。
// ---------------------------------------------------------------------------

/** workspace root（workspace 库 scope 寻址基准；scope 默认 workspace 库） */
const ROOT = 'C:\\demo\\beta';
const WORKSPACE_PARAMS = { scope: 'workspace', root: ROOT } as const;

/** 模型清单 fixture：agent_run 载荷用于翻页矩阵（60 = 1 整页 + 10）。 */
const MODELS: ModelInfo[] = [
  { name: 'workspace', count: 0 },
  { name: 'agent_run', count: 60 },
  { name: 'agent_event', count: 3 },
];

function envelopes(count: number, from = 0): RecordEnvelope[] {
  return Array.from({ length: count }, (_, index) => ({
    key: from + index,
    value: { id: from + index },
  }));
}

/** 按命令名分发：db_models 恒回清单，db_records 按 offset/limit 切库存，
 * 回分页信封（records 区间 + total = 库存全量计数）。 */
function mockDispatch(inventory: RecordEnvelope[] = []) {
  invokeMock.mockImplementation(
    (command: string, params?: { model?: string; offset?: number; limit?: number }) => {
      if (command === 'db_models') {
        return Promise.resolve(MODELS.map((model) => ({ ...model })));
      }
      if (command === 'db_records') {
        const offset = params?.offset ?? 0;
        const limit = params?.limit ?? 50;
        const records = inventory.slice(offset, offset + limit).map((e) => ({ ...e }));
        return Promise.resolve({ records, total: inventory.length });
      }
      return Promise.resolve(null);
    },
  );
}

/** mock.calls 中某命令的调用次数。 */
function countOf(command: string): number {
  return invokeMock.mock.calls.filter(([name]) => name === command).length;
}

/** mock.calls 中某命令最近一次的参数。 */
function lastParamsOf(command: string): Record<string, unknown> | undefined {
  const last = invokeMock.mock.calls.filter(([name]) => name === command).at(-1);
  return last?.[1] as Record<string, unknown> | undefined;
}

async function selectModel(result: { current: ReturnType<typeof useDbInspector> }, name: string) {
  act(() => {
    result.current.selectModel(name);
  });
  await waitFor(() => expect(result.current.selected).toBe(name));
}

describe('useDbInspector：挂载取数', () => {
  beforeEach(() => {
    invokeMock.mockReset();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  // 置于套件首位（沿 useWorkspaces 稳定判据模式）：失控循环在逐拍解析下被
  // 稳定判据快速观测并判失败
  it('取数链稳定：挂载后调用数不再增长（无轮询、无恢复循环、无多余 db_records）', async () => {
    // 每个响应经 setTimeout(0) 宏任务逐拍解析：失控循环每拍只走一轮，可被稳定判据观测
    invokeMock.mockImplementation(
      (command: string) =>
        new Promise((resolve) =>
          setTimeout(() => resolve(command === 'db_models' ? MODELS : []), 0),
        ),
    );
    const { result } = renderHook(() => useDbInspector(ROOT));

    let previous = -1;
    await waitFor(
      () => {
        const current = invokeMock.mock.calls.length;
        if (current !== previous) {
          previous = current;
          throw new Error('取数链尚未稳定');
        }
      },
      { timeout: 3000, interval: 50 },
    );

    expect(countOf('db_models')).toBe(1);
    expect(invokeMock).toHaveBeenCalledTimes(1); // 除挂载取数外无任何命令
    expect(result.current.models).toHaveLength(3);
    expect(result.current.error).toBeNull();
  });

  it('挂载即 invoke("db_models") 恰一次，loading 置位后随成功清除', async () => {
    let resolveLoad: (models: ModelInfo[]) => void = () => {};
    invokeMock.mockImplementation(
      (command: string) =>
        new Promise<ModelInfo[]>((resolve) => {
          if (command === 'db_models') resolveLoad = resolve;
        }),
    );
    const { result } = renderHook(() => useDbInspector(ROOT));

    // 挂载取数进行中：loading 置位（挂载 effect 显式置位）
    expect(result.current.loading).toBe(true);

    await act(async () => {
      resolveLoad([...MODELS]);
    });
    expect(result.current.loading).toBe(false);
    expect(result.current.models).toHaveLength(3);
    expect(result.current.error).toBeNull();
    expect(invokeMock).toHaveBeenCalledWith('db_models', WORKSPACE_PARAMS);
    expect(countOf('db_models')).toBe(1);
  });

  it('静置后调用数不增长且未选中模型时不取记录（AC-7 只读取数纪律）', async () => {
    mockDispatch();
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));
    const baseline = invokeMock.mock.calls.length;

    await act(async () => {
      await new Promise((resolve) => setTimeout(resolve, 20));
    });

    expect(invokeMock.mock.calls.length).toBe(baseline);
    expect(countOf('db_records')).toBe(0); // 未选中模型不取数
    expect(result.current.records).toEqual([]);
  });
});

describe('useDbInspector：selectModel 与翻页', () => {
  beforeEach(() => {
    invokeMock.mockReset();
  });

  it('selectModel 重置 offset=0 并以 {scope, root, model, offset:0, limit:50} 取第一页', async () => {
    const inventory = envelopes(60);
    mockDispatch(inventory);
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await selectModel(result, 'agent_run');

    await waitFor(() => expect(result.current.records).toHaveLength(50));
    expect(invokeMock).toHaveBeenCalledWith('db_records', {
      ...WORKSPACE_PARAMS,
      model: 'agent_run',
      offset: 0,
      limit: 50,
    });
    expect(result.current.offset).toBe(0);
    expect(result.current.hasMore).toBe(true); // 整页（50）→ 可能还有下一页
  });

  it('连续两次 selectModel：两次动作均触发取数，最终状态与最后选择一致', async () => {
    mockDispatch(envelopes(10));
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(countOf('db_records')).toBe(1));
    await selectModel(result, 'agent_event');
    await waitFor(() => expect(countOf('db_records')).toBe(2));

    expect(result.current.selected).toBe('agent_event');
    expect(result.current.offset).toBe(0);
    expect(lastParamsOf('db_records')).toEqual({
      ...WORKSPACE_PARAMS,
      model: 'agent_event',
      offset: 0,
      limit: 50,
    });
  });

  it('nextPage / prevPage 以 PAGE_SIZE 步进取对应页，refresh 以当前 offset 重取', async () => {
    const inventory = envelopes(120);
    mockDispatch(inventory);
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(result.current.records).toHaveLength(50));

    act(() => {
      result.current.nextPage();
    });
    await waitFor(() => expect(result.current.offset).toBe(50));
    await waitFor(() => expect(result.current.records[0].key).toBe(50));
    expect(lastParamsOf('db_records')).toEqual({
      ...WORKSPACE_PARAMS,
      model: 'agent_run',
      offset: 50,
      limit: 50,
    });

    act(() => {
      result.current.refresh();
    });
    await waitFor(() => expect(countOf('db_records')).toBe(3));
    expect(lastParamsOf('db_records')).toEqual({
      ...WORKSPACE_PARAMS,
      model: 'agent_run',
      offset: 50,
      limit: 50,
    });

    act(() => {
      result.current.prevPage();
    });
    await waitFor(() => expect(result.current.offset).toBe(0));
    await waitFor(() => expect(result.current.records[0].key).toBe(0));
    expect(lastParamsOf('db_records')).toEqual({
      ...WORKSPACE_PARAMS,
      model: 'agent_run',
      offset: 0,
      limit: 50,
    });
  });

  it('首页 prevPage 不动：offset 保持 0 且不触发负 offset 取数', async () => {
    mockDispatch(envelopes(10));
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(result.current.records).toHaveLength(10));
    const recordsCalls = countOf('db_records');

    act(() => {
      result.current.prevPage();
    });

    expect(result.current.offset).toBe(0);
    expect(countOf('db_records')).toBe(recordsCalls); // offset 未变 → 不重取
  });

  it('total 导出页界：首页 hasMore 由 total 判定，翻页拼接不重不漏', async () => {
    mockDispatch(envelopes(60)); // 库存 60 = 1 整页 50 + 10
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(result.current.records).toHaveLength(50));

    // total 为接口全量计数快照（非本页条数），页界全部由其导出
    expect(result.current.total).toBe(60);
    expect(result.current.page).toBe(1); // offset 0 / 50 + 1
    expect(result.current.hasMore).toBe(true); // 0 + 50 < 60
    const page1Keys = result.current.records.map((envelope) => envelope.key);

    act(() => {
      result.current.nextPage();
    });
    await waitFor(() => expect(result.current.records[0]?.key).toBe(50));
    const page2Keys = result.current.records.map((envelope) => envelope.key);

    expect(result.current.total).toBe(60); // 翻页不改 total（恒全量计数）
    expect(result.current.page).toBe(2); // offset 50 / 50 + 1
    expect(result.current.hasMore).toBe(false); // 50 + 10 < 60 不成立

    const union = [...page1Keys, ...page2Keys];
    expect(new Set(union).size).toBe(union.length); // 不重
    expect(union).toHaveLength(60); // 不漏
    expect(union.every((key, index) => key === index)).toBe(true); // 拼接即全集自然序
  });

  it('total 恰为 PAGE_SIZE 整数倍：末页 next 禁用、无幽灵空页（AC-4 / DD5）', async () => {
    mockDispatch(envelopes(100)); // 库存 100 = 恰两整页
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(result.current.records).toHaveLength(50));

    expect(result.current.total).toBe(100);
    expect(result.current.totalPages).toBe(2); // max(1, ceil(100/50))
    expect(result.current.hasMore).toBe(true); // 0 + 50 < 100

    act(() => {
      result.current.nextPage();
    });
    await waitFor(() => expect(result.current.records[0]?.key).toBe(50));
    expect(result.current.page).toBe(2);
    // 末页（50 + 50 == total）：hasMore 显式 false —— 废除旧
    // `records.length === PAGE_SIZE` 启发式（旧口径此处误判 true 并翻出空页）
    expect(result.current.hasMore).toBe(false);

    act(() => {
      result.current.nextPage();
    });
    // 锚定在越界取数完成（offset 与在途标志双双落定），避免读到上一页残留
    await waitFor(() => expect(result.current.recordsLoading).toBe(false));
    expect(result.current.offset).toBe(100);
    // 越过末页：空页但 total 恒全量，页码自洽不崩
    expect(result.current.records).toHaveLength(0);
    expect(result.current.total).toBe(100);
    expect(result.current.page).toBe(3);
    expect(result.current.hasMore).toBe(false);
  });

  it('total=0 / total=1 / 超大 total：totalPages 取 max(1, …) 不除零、页界不 NaN', async () => {
    // total = 0（空模型）
    mockDispatch(envelopes(0));
    const empty = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(empty.result.current.loading).toBe(false));
    await selectModel(empty.result, 'agent_run');
    await waitFor(() => expect(empty.result.current.records).toHaveLength(0));
    expect(empty.result.current.total).toBe(0);
    expect(empty.result.current.totalPages).toBe(1); // max(1, ceil(0/50))
    expect(empty.result.current.page).toBe(1);
    expect(empty.result.current.hasMore).toBe(false); // 0 + 0 < 0 不成立

    // total = 1（单条）：恰一页
    mockDispatch(envelopes(1));
    const single = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(single.result.current.loading).toBe(false));
    await selectModel(single.result, 'agent_run');
    await waitFor(() => expect(single.result.current.records).toHaveLength(1));
    expect(single.result.current.totalPages).toBe(1);
    expect(single.result.current.hasMore).toBe(false); // 0 + 1 < 1 不成立

    // 超大 total（Number.MAX_SAFE_INTEGER 量级）：页界运算不溢出、不 NaN
    const hugeTotal = Number.MAX_SAFE_INTEGER;
    invokeMock.mockImplementation((command: string) => {
      if (command === 'db_models') return Promise.resolve(MODELS.map((m) => ({ ...m })));
      return Promise.resolve({ records: envelopes(50), total: hugeTotal });
    });
    const huge = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(huge.result.current.loading).toBe(false));
    await selectModel(huge.result, 'agent_run');
    await waitFor(() => expect(huge.result.current.records).toHaveLength(50));

    expect(huge.result.current.total).toBe(hugeTotal);
    expect(huge.result.current.totalPages).toBe(Math.ceil(hugeTotal / 50));
    expect(Number.isFinite(huge.result.current.totalPages)).toBe(true);
    expect(huge.result.current.hasMore).toBe(true); // 0 + 50 < huge
  });
});

// ---------------------------------------------------------------------------
// scope / root 切换重置与重取（desktop-workspace-db-split）：scope 态默认
// workspace 库，切全局库 / 换 root 均重置选中模型与分页并重取清单（两库清单
// 互不混列，选中与页码不跨库沿用）。
// ---------------------------------------------------------------------------

describe('useDbInspector：scope / root 切换重置与重取', () => {
  beforeEach(() => {
    invokeMock.mockReset();
  });

  it('默认 scope 为 workspace 库：挂载即携 (scope: "workspace", root) 取清单', async () => {
    mockDispatch();
    const { result } = renderHook(() => useDbInspector(ROOT));

    await waitFor(() => expect(result.current.models).toHaveLength(3));

    expect(result.current.scope).toBe('workspace');
    expect(invokeMock).toHaveBeenCalledWith('db_models', WORKSPACE_PARAMS);
  });

  it('setScope 切换后重置选中模型（复位 null）与分页（offset 回 0），并以新 scope 重取清单', async () => {
    mockDispatch(envelopes(10));
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(result.current.records).toHaveLength(10));

    act(() => {
      result.current.setScope('user');
    });

    await waitFor(() => expect(lastParamsOf('db_models')).toEqual({ scope: 'user', root: ROOT }));
    expect(result.current.scope).toBe('user');
    expect(result.current.selected).toBeNull();
    expect(result.current.offset).toBe(0);
    expect(result.current.records).toEqual([]);
  });

  it('root 变更同口径：重置选中与分页，清单与记录以新 root 重取', async () => {
    mockDispatch(envelopes(10));
    const NEXT_ROOT = 'C:\\demo\\gamma';
    const { result, rerender } = renderHook(
      (props: { root: string }) => useDbInspector(props.root),
      { initialProps: { root: ROOT } },
    );
    await waitFor(() => expect(result.current.loading).toBe(false));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(result.current.records).toHaveLength(10));

    rerender({ root: NEXT_ROOT });

    await waitFor(() =>
      expect(lastParamsOf('db_models')).toEqual({ scope: 'workspace', root: NEXT_ROOT }),
    );
    expect(result.current.selected).toBeNull();
    expect(result.current.offset).toBe(0);
    expect(result.current.records).toEqual([]);
  });

  it('root 参数 str 边界逐档（空串 blank / 超长 >1000 字符 / 特殊字符 emoji / 正常值）均同口径复位并以新 root 重取', async () => {
    // root 仅作 IPC 透传与 effect 依赖键，形态不影响分支——四档逐一验证复位语义
    const roots = ['', `C:\\demo\\${'x'.repeat(1001)}`, '根\n路径\0🎯', 'C:\\demo\\normal'];
    mockDispatch(envelopes(10));
    const { result, rerender } = renderHook(
      (props: { root: string }) => useDbInspector(props.root),
      { initialProps: { root: ROOT } },
    );
    await waitFor(() => expect(result.current.loading).toBe(false));

    for (const nextRoot of roots) {
      await selectModel(result, 'agent_run');
      await waitFor(() => expect(result.current.records).toHaveLength(10));

      rerender({ root: nextRoot });

      // 每档 root 变更即复位选中与分页，并以新 root 透传重取清单
      await waitFor(() =>
        expect(lastParamsOf('db_models')).toEqual({ scope: 'workspace', root: nextRoot }),
      );
      expect(result.current.selected).toBeNull();
      expect(result.current.offset).toBe(0);
      expect(result.current.records).toEqual([]);
      expect(result.current.total).toBe(0); // 页界快照同口径复位（不呈伪 total）
    }
  });
});

describe('useDbInspector：错误态（查询轨 inline，无 toast）', () => {
  beforeEach(() => {
    invokeMock.mockReset();
  });

  it('db_models reject：error 置位含错误串、models 保持空数组、无未捕获异常', async () => {
    invokeMock.mockRejectedValue(new Error('db: 清单打开失败'));
    const { result } = renderHook(() => useDbInspector(ROOT));

    await waitFor(() => expect(result.current.error).not.toBeNull());

    expect(result.current.error).toContain('db: 清单打开失败');
    expect(result.current.models).toEqual([]);
    expect(result.current.loading).toBe(false);
  });

  it('db_records reject：recordsError 置位、已选模型与清单不丢失', async () => {
    invokeMock.mockImplementation((command: string) => {
      if (command === 'db_models') return Promise.resolve([...MODELS]);
      return Promise.reject(new Error('db: 未知模型'));
    });
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.models).toHaveLength(3));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(result.current.recordsError).not.toBeNull());

    expect(result.current.recordsError).toContain('db: 未知模型');
    expect(result.current.selected).toBe('agent_run'); // 已选模型不丢失
    expect(result.current.models).toHaveLength(3); // 清单不丢失
    expect(result.current.recordsLoading).toBe(false);
    expect(result.current.error).toBeNull(); // 清单轨与记录轨错误互不顶替
  });
});

describe('useDbInspector：加载态、翻页竞态取消守卫与 refresh 严格重发', () => {
  beforeEach(() => {
    invokeMock.mockReset();
  });

  it('未选中模型静置：recordsLoading 保持 false、recordsError 为 null（无幽灵加载态）', async () => {
    mockDispatch(envelopes(10));
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    expect(result.current.recordsLoading).toBe(false);
    expect(result.current.recordsError).toBeNull();
    expect(result.current.records).toEqual([]);
    expect(countOf('db_records')).toBe(0);
  });

  it('选中模型取数进行中：recordsLoading 置位，完成后清除并落页', async () => {
    let resolveRecords: (page: RecordsPage) => void = () => {};
    invokeMock.mockImplementation((command: string) => {
      if (command === 'db_models') return Promise.resolve([...MODELS]);
      return new Promise<RecordsPage>((resolve) => {
        resolveRecords = resolve;
      });
    });
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    act(() => {
      result.current.selectModel('agent_run');
    });
    await waitFor(() => expect(result.current.recordsLoading).toBe(true));
    expect(result.current.recordsError).toBeNull(); // 在途不误报错误

    await act(async () => {
      resolveRecords({ records: envelopes(5), total: 5 });
    });
    expect(result.current.recordsLoading).toBe(false);
    expect(result.current.records).toHaveLength(5);
    expect(result.current.records[0]?.key).toBe(0);
  });

  it('翻页竞态：旧页响应迟到不顶替新页（取消守卫生效，新页数据不被污染）', async () => {
    const resolvers: Array<(page: RecordsPage) => void> = [];
    invokeMock.mockImplementation((command: string) => {
      if (command === 'db_models') return Promise.resolve([...MODELS]);
      return new Promise<RecordsPage>((resolve) => {
        resolvers.push(resolve);
      });
    });
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    act(() => {
      result.current.selectModel('agent_run');
    });
    await waitFor(() => expect(result.current.recordsLoading).toBe(true)); // 第 1 页在途

    act(() => {
      result.current.nextPage(); // 翻页即取消第 1 页请求（cleanup 置 cancelled）
    });
    await waitFor(() => expect(resolvers.length).toBe(2)); // 第 2 页请求已发出

    await act(async () => {
      resolvers[1]({ records: envelopes(3, 50), total: 53 }); // 新页（offset 50）先返回
    });
    await waitFor(() => expect(result.current.records[0]?.key).toBe(50));

    await act(async () => {
      resolvers[0]({ records: envelopes(3, 0), total: 3 }); // 旧页迟到返回
    });
    // 取消守卫：旧页响应被丢弃，不顶替新页、不扰加载态
    expect(result.current.records[0]?.key).toBe(50);
    expect(result.current.records).toHaveLength(3);
    expect(result.current.recordsLoading).toBe(false);
  });

  it('翻页竞态（错误向）：旧页迟到失败不置 recordsError、新页数据不丢', async () => {
    const resolvers: Array<(page: RecordsPage) => void> = [];
    const rejectors: Array<(error: unknown) => void> = [];
    invokeMock.mockImplementation((command: string) => {
      if (command === 'db_models') return Promise.resolve([...MODELS]);
      return new Promise<RecordsPage>((resolve, reject) => {
        resolvers.push(resolve);
        rejectors.push(reject);
      });
    });
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    act(() => {
      result.current.selectModel('agent_run');
    });
    await waitFor(() => expect(result.current.recordsLoading).toBe(true));

    act(() => {
      result.current.nextPage();
    });
    await waitFor(() => expect(resolvers.length).toBe(2));

    await act(async () => {
      resolvers[1]({ records: envelopes(3, 50), total: 53 }); // 新页成功返回
    });
    await waitFor(() => expect(result.current.records[0]?.key).toBe(50));

    await act(async () => {
      rejectors[0](new Error('旧请求迟到失败')); // 已取消的旧请求后置失败
    });
    // 取消守卫：迟到失败不置错、数据不丢、无幽灵加载态
    expect(result.current.recordsError).toBeNull();
    expect(result.current.records[0]?.key).toBe(50);
    expect(result.current.recordsLoading).toBe(false);
  });

  it('refresh 连按两次：每次均重发当前页取数（tick 严格递增，第二次不失效）', async () => {
    mockDispatch(envelopes(60));
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(countOf('db_records')).toBe(1));

    act(() => {
      result.current.refresh();
    });
    await waitFor(() => expect(countOf('db_records')).toBe(2));

    act(() => {
      result.current.refresh();
    });
    await waitFor(() => expect(countOf('db_records')).toBe(3));

    expect(lastParamsOf('db_records')).toEqual({
      ...WORKSPACE_PARAMS,
      model: 'agent_run',
      offset: 0,
      limit: 50,
    });
    expect(result.current.records).toHaveLength(50);
  });
});

// ---------------------------------------------------------------------------
// 生成绑定调用面（AC-5 回归锁定）：db_models / db_records 裸 invoke → typed
// bindings 机械替换后，invoke 命令名与参数逐字不变（生成绑定底层仍走同模块
// invoke，mock 机制切换后依旧生效）。
// ---------------------------------------------------------------------------

describe('useDbInspector：生成绑定调用面', () => {
  beforeEach(() => {
    invokeMock.mockReset();
  });

  it('经生成绑定入口后 invoke 收到 "db_models" + { scope, root } 与 "db_records" + { scope, root, model, offset, limit }，分页参数与取数透传不变', async () => {
    mockDispatch(envelopes(60));
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.models).toHaveLength(3));
    expect(invokeMock).toHaveBeenCalledWith('db_models', WORKSPACE_PARAMS);

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(result.current.records).toHaveLength(50));
    expect(invokeMock).toHaveBeenCalledWith('db_records', {
      ...WORKSPACE_PARAMS,
      model: 'agent_run',
      offset: 0,
      limit: 50,
    });

    act(() => {
      result.current.nextPage();
    });
    await waitFor(() => expect(result.current.offset).toBe(50));
    expect(lastParamsOf('db_records')).toEqual({
      ...WORKSPACE_PARAMS,
      model: 'agent_run',
      offset: 50,
      limit: 50,
    });
  });

  it('未选中模型不取记录（零 IPC 纪律保持）、翻页 offset 步进参数不变', async () => {
    mockDispatch(envelopes(10));
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    expect(countOf('db_records')).toBe(0);
    expect(result.current.records).toEqual([]);
  });

  it('db_models / db_records reject → 双轨 inline 错误态置位、已选模型不丢失不变', async () => {
    invokeMock.mockImplementation((command: string) => {
      if (command === 'db_models') return Promise.resolve([...MODELS]);
      return Promise.reject(new Error('db: 未知模型'));
    });
    const { result } = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(result.current.models).toHaveLength(3));

    await selectModel(result, 'agent_run');
    await waitFor(() => expect(result.current.recordsError).toContain('db: 未知模型'));
    expect(result.current.selected).toBe('agent_run');
    expect(result.current.models).toHaveLength(3);

    invokeMock.mockReset();
    invokeMock.mockRejectedValue(new Error('db: 清单打开失败'));
    const modelsFailed = renderHook(() => useDbInspector(ROOT));
    await waitFor(() => expect(modelsFailed.result.current.error).toContain('db: 清单打开失败'));
    expect(modelsFailed.result.current.models).toEqual([]);
  });
});

