import { act, renderHook, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import type { ExploreRecord } from '../../../types/dto';
import { useExploreList } from './use-explore-list';

const { invokeMock } = vi.hoisted(() => ({ invokeMock: vi.fn() }));

vi.mock('@tauri-apps/api/core', () => ({
  invoke: invokeMock,
}));

// ---------------------------------------------------------------------------
// fixture（对齐 store::ExploreRecord serde camelCase）
// ---------------------------------------------------------------------------

const ROOT = 'C:\\demo\\alpha';

function record(id: number, name: string, root = ROOT): ExploreRecord {
  return {
    id,
    root,
    name,
    title: name,
    workflowType: 'requirement',
    promotedTo: null,
    sessionId: null,
    createdAt: 1727000000000 + id,
    updatedAt: 1727000000000 + id,
  };
}

beforeEach(() => {
  invokeMock.mockReset();
});

afterEach(() => {
  vi.useRealTimers();
});

describe('useExploreList：清单取数纪律（AC-8）', () => {
  it('有效 root 挂载：以 { root } 发起 list_explore_records 恰一次，records 呈现返回序', async () => {
    const seeded = [record(1, 'api-retry'), record(2, 'layout-design')];
    invokeMock.mockResolvedValue(seeded);

    const { result } = renderHook(() => useExploreList(ROOT));

    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(invokeMock).toHaveBeenCalledTimes(1);
    expect(invokeMock).toHaveBeenCalledWith('list_explore_records', { root: ROOT });
    expect(result.current.records).toEqual(seeded);
    expect(result.current.error).toBeNull();
  });

  it('root 为 null：不发起任何取数，records 为空态', () => {
    const { result } = renderHook(() => useExploreList(null));

    expect(invokeMock).not.toHaveBeenCalled();
    expect(result.current.records).toEqual([]);
    expect(result.current.loading).toBe(false);
    expect(result.current.error).toBeNull();
  });

  it('root 变更（A→B）：以新 root 重取，旧 root 的在途结果不覆盖新态', async () => {
    let resolveA: (value: ExploreRecord[]) => void = () => {};
    invokeMock.mockImplementation((_command: string, params?: { root?: string }) => {
      if (params?.root === 'C:\\demo\\a') {
        return new Promise<ExploreRecord[]>((resolve) => {
          resolveA = resolve;
        });
      }
      return Promise.resolve([record(9, 'b-record', 'C:\\demo\\b')]);
    });

    const { result, rerender } = renderHook(
      ({ root }: { root: string | null }) => useExploreList(root),
      { initialProps: { root: 'C:\\demo\\a' } },
    );
    await waitFor(() => expect(result.current.loading).toBe(true));

    rerender({ root: 'C:\\demo\\b' });
    await waitFor(() =>
      expect(result.current.records).toEqual([record(9, 'b-record', 'C:\\demo\\b')]),
    );

    // 旧 root 的在途结果迟到：不得覆盖新态（cancelled 抑制，ChangeList 同款竞态语义）
    resolveA([record(1, 'stale-a', 'C:\\demo\\a')]);
    await act(async () => {});
    expect(result.current.records).toEqual([record(9, 'b-record', 'C:\\demo\\b')]);
    const roots = invokeMock.mock.calls.map(([, params]) => (params as { root: string }).root);
    expect(roots).toEqual(['C:\\demo\\a', 'C:\\demo\\b']);
  });

  it('list_explore_records reject：error 置位、records 保持空态不崩', async () => {
    invokeMock.mockRejectedValue(new Error('IPC 断开'));

    const { result } = renderHook(() => useExploreList(ROOT));

    await waitFor(() => expect(result.current.error).not.toBeNull());
    expect(result.current.error).toContain('IPC 断开');
    expect(result.current.records).toEqual([]);
    expect(result.current.loading).toBe(false);
  });

  it('refresh 显式调用恰发一次取数；无 root 时 refresh 为 no-op', async () => {
    invokeMock.mockResolvedValue([record(1, 'api-retry')]);
    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(invokeMock).toHaveBeenCalledTimes(1);

    act(() => {
      result.current.refresh();
    });
    await waitFor(() => expect(invokeMock.mock.calls.length).toBe(2));
    expect(invokeMock).toHaveBeenLastCalledWith('list_explore_records', { root: ROOT });

    const blank = renderHook(() => useExploreList(null));
    act(() => {
      blank.result.current.refresh();
    });
    await act(async () => {});
    expect(invokeMock.mock.calls.length).toBe(2);
  });
});

describe('useExploreList：动作薄封装（create / rename / remove 后刷新，AC-8）', () => {
  it('create：发起 create_explore_record，成功后以当前 root 重新取数、新记录入列', async () => {
    const initial = [record(1, 'api-retry')];
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') {
        return Promise.resolve(
          invokeMock.mock.calls.filter(([name]) => name === 'list_explore_records').length >= 2
            ? [...initial, record(2, 'new-topic')]
            : initial,
        );
      }
      if (command === 'create_explore_record') {
        return Promise.resolve(record(2, 'new-topic'));
      }
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toEqual(initial));

    act(() => {
      result.current.create('new-topic');
    });

    await waitFor(() =>
      expect(result.current.records).toEqual([record(1, 'api-retry'), record(2, 'new-topic')]),
    );
    expect(invokeMock).toHaveBeenCalledWith('create_explore_record', {
      root: ROOT,
      name: 'new-topic',
    });
  });

  it('rename / remove：分别发起对应命令，成功后列表刷新反映变更', async () => {
    const initial = [record(1, 'old-name'), record(2, 'api-retry')];
    invokeMock.mockImplementation((command: string, params?: Record<string, unknown>) => {
      if (command === 'list_explore_records') {
        const renamed = invokeMock.mock.calls.some(([name]) => name === 'rename_explore_record');
        const removed = invokeMock.mock.calls.some(([name]) => name === 'delete_explore_record');
        if (renamed && !removed)
          return Promise.resolve([record(1, 'new-name'), record(2, 'api-retry')]);
        if (renamed && removed) return Promise.resolve([record(1, 'new-name')]);
        return Promise.resolve(initial);
      }
      if (command === 'rename_explore_record') {
        return Promise.resolve(record(1, String(params?.newName)));
      }
      if (command === 'delete_explore_record') {
        return Promise.resolve(true);
      }
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toEqual(initial));

    act(() => {
      result.current.rename('old-name', 'new-name');
    });
    await waitFor(() =>
      expect(result.current.records).toEqual([record(1, 'new-name'), record(2, 'api-retry')]),
    );
    expect(invokeMock).toHaveBeenCalledWith('rename_explore_record', {
      root: ROOT,
      name: 'old-name',
      newName: 'new-name',
    });

    act(() => {
      result.current.remove('api-retry');
    });
    await waitFor(() => expect(result.current.records).toEqual([record(1, 'new-name')]));
    expect(invokeMock).toHaveBeenCalledWith('delete_explore_record', {
      root: ROOT,
      name: 'api-retry',
    });
  });

  it('动作 reject：error 置位落 error 态，不中断页面（清单保持原值）', async () => {
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') {
        return Promise.resolve([record(1, 'api-retry')]);
      }
      if (command === 'create_explore_record') {
        return Promise.reject(new Error('记录已存在'));
      }
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toHaveLength(1));

    act(() => {
      result.current.create('api-retry');
    });

    await waitFor(() => expect(result.current.error).toContain('记录已存在'));
    expect(result.current.records).toHaveLength(1);
  });
});

// ---------------------------------------------------------------------------
// 强化断言（变异补杀）：无 root 动作守卫、rename / remove 失败语义、root
// 切换过渡门闩与迟到现在语义。
// ---------------------------------------------------------------------------

describe('useExploreList：无 root 动作守卫与失败语义（AC-8）', () => {
  it('root 为 null：create / rename / remove 三个动作均为 no-op（零 IPC）', async () => {
    const { result } = renderHook(() => useExploreList(null));

    act(() => {
      result.current.create('topic');
      result.current.rename('topic', 'renamed');
      result.current.remove('topic');
    });
    await act(async () => {});

    expect(invokeMock).not.toHaveBeenCalled();
  });

  it('rename reject：error 置位（清单不被污染）', async () => {
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') return Promise.resolve([record(1, 'old-name')]);
      if (command === 'rename_explore_record') return Promise.reject(new Error('新名已占用'));
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toHaveLength(1));

    act(() => {
      result.current.rename('old-name', 'clash');
    });

    await waitFor(() => expect(result.current.error).toContain('新名已占用'));
    expect(result.current.records).toEqual([record(1, 'old-name')]);
  });

  it('remove reject：error 置位（记录仍在清单）', async () => {
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') return Promise.resolve([record(1, 'keep')]);
      if (command === 'delete_explore_record') return Promise.reject(new Error('删除失败'));
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toHaveLength(1));

    act(() => {
      result.current.remove('keep');
    });

    await waitFor(() => expect(result.current.error).toContain('删除失败'));
    expect(result.current.records).toEqual([record(1, 'keep')]);
  });
});

describe('useExploreList：root 切换过渡与迟到现在语义（AC-8）', () => {
  it('root 切换过渡轮：旧 root 记录不呈现（新 root 在途时为空态）', async () => {
    invokeMock.mockImplementation((_command: string, params?: { root?: string }) => {
      if (params?.root === 'C:\\demo\\a') {
        return Promise.resolve([record(1, 'a-record', 'C:\\demo\\a')]);
      }
      return new Promise<ExploreRecord[]>(() => {});
    });

    const { result, rerender } = renderHook(
      ({ root }: { root: string | null }) => useExploreList(root),
      { initialProps: { root: 'C:\\demo\\a' } },
    );
    await waitFor(() =>
      expect(result.current.records).toEqual([record(1, 'a-record', 'C:\\demo\\a')]),
    );

    rerender({ root: 'C:\\demo\\b' });
    await act(async () => {});

    expect(result.current.records).toEqual([]);
  });

  it('root 切换竞态：旧 root 迟到的 reject 不置错误、不污染新态', async () => {
    let rejectA: (err: unknown) => void = () => {};
    invokeMock.mockImplementation((_command: string, params?: { root?: string }) => {
      if (params?.root === 'C:\\demo\\a') {
        return new Promise<ExploreRecord[]>((_resolve, reject) => {
          rejectA = reject;
        });
      }
      return Promise.resolve([record(9, 'b-record', 'C:\\demo\\b')]);
    });

    const { result, rerender } = renderHook(
      ({ root }: { root: string | null }) => useExploreList(root),
      { initialProps: { root: 'C:\\demo\\a' } },
    );
    rerender({ root: 'C:\\demo\\b' });
    await waitFor(() =>
      expect(result.current.records).toEqual([record(9, 'b-record', 'C:\\demo\\b')]),
    );

    await act(async () => {
      rejectA(new Error('迟到的清单失败'));
    });
    expect(result.current.error).toBeNull();
    expect(result.current.records).toEqual([record(9, 'b-record', 'C:\\demo\\b')]);
  });
});

// ---------------------------------------------------------------------------
// 生成绑定调用面（AC-5 回归锁定）：list_explore_records / create_explore_record
// / rename_explore_record / delete_explore_record 裸 invoke → typed bindings
// 机械替换后，命令名与参数逐字不变（生成绑定底层仍走同模块 invoke，mock 机制
// 切换后依旧生效）。
// ---------------------------------------------------------------------------

describe('useExploreList：生成绑定调用面', () => {
  it('四命令经生成绑定入口后命令名与参数逐字不变，动作后以当前 root 重新取数语义不变', async () => {
    const initial = [record(1, 'api-retry')];
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') {
        const created = invokeMock.mock.calls.some(([name]) => name === 'create_explore_record');
        return Promise.resolve(created ? [...initial, record(2, 'new-topic')] : initial);
      }
      if (command === 'create_explore_record') {
        return Promise.resolve(record(2, 'new-topic'));
      }
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toEqual(initial));
    expect(invokeMock).toHaveBeenCalledWith('list_explore_records', { root: ROOT });

    act(() => {
      result.current.create('new-topic');
    });
    await waitFor(() => expect(result.current.records).toHaveLength(2));
    expect(invokeMock).toHaveBeenCalledWith('create_explore_record', {
      root: ROOT,
      name: 'new-topic',
    });
    expect(invokeMock).toHaveBeenLastCalledWith('list_explore_records', { root: ROOT });
  });

  it('root 为 null 时四动作均 no-op（零 IPC 守卫在绑定切换后保持）', async () => {
    const { result } = renderHook(() => useExploreList(null));

    act(() => {
      result.current.create('topic');
      result.current.rename('topic', 'renamed');
      result.current.remove('topic');
      result.current.refresh();
    });
    await act(async () => {});

    expect(invokeMock.mock.calls).toHaveLength(0);
  });

  it('动作 reject → error 置位、清单不被污染（清单保持原值）不变', async () => {
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') return Promise.resolve([record(1, 'keep')]);
      if (command === 'delete_explore_record') return Promise.reject(new Error('删除失败'));
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toHaveLength(1));

    act(() => {
      result.current.remove('keep');
    });
    await waitFor(() => expect(result.current.error).toContain('删除失败'));

    expect(result.current.records).toEqual([record(1, 'keep')]);
  });
});

// ---------------------------------------------------------------------------
// 详情页动作薄封装（explore-name-file-binding AC-5 / AC-8）：updateTitle(name,
// title) / promote(name) —— invoke 后 refresh；失败落 error 且向外 rethrow
// 供详情页行内错误捕获；无 root 守卫为 no-op（零 IPC）。
// ---------------------------------------------------------------------------

/** 显式 title / promotedTo 形态 fixture（title ≠ name 双字段可辨）。 */
function titledRecord(
  id: number,
  name: string,
  title: string,
  promotedTo: string | null = null,
): ExploreRecord {
  return { ...record(id, name), title, promotedTo };
}

describe('useExploreList：详情页动作（updateTitle / promote，AC-5 / AC-8）', () => {
  it('updateTitle：invoke("update_explore_title", { root, name, title }) → 成功后以当前 root 重新取数', async () => {
    const titled = titledRecord(1, 'api-retry', '接口重试策略');
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') {
        const updated = invokeMock.mock.calls.some(([n]) => n === 'update_explore_title');
        return Promise.resolve(updated ? [titled] : [record(1, 'api-retry')]);
      }
      if (command === 'update_explore_title') return Promise.resolve(titled);
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toEqual([record(1, 'api-retry')]));

    await act(async () => {
      await result.current.updateTitle('api-retry', '接口重试策略');
    });

    expect(invokeMock).toHaveBeenCalledWith('update_explore_title', {
      root: ROOT,
      name: 'api-retry',
      title: '接口重试策略',
    });
    await waitFor(() => expect(result.current.records).toEqual([titled]));
    expect(invokeMock).toHaveBeenLastCalledWith('list_explore_records', { root: ROOT });
  });

  it('promote：invoke("promote_explore", { root, name, workflowType }) → 成功后 refresh（promoted 态随清单取数回流）', async () => {
    const promoted = titledRecord(1, 'api-retry', '接口重试策略', 'chg-018f3a-0001');
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') {
        const promotedCalled = invokeMock.mock.calls.some(([n]) => n === 'promote_explore');
        return Promise.resolve(
          promotedCalled ? [promoted] : [titledRecord(1, 'api-retry', '接口重试策略')],
        );
      }
      if (command === 'promote_explore') {
        return Promise.resolve({ changeId: 'chg-018f3a-0001', changeName: 'api-retry' });
      }
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() =>
      expect(result.current.records).toEqual([titledRecord(1, 'api-retry', '接口重试策略')]),
    );

    await act(async () => {
      await result.current.promote('api-retry', 'requirement');
    });

    expect(invokeMock).toHaveBeenCalledWith('promote_explore', {
      root: ROOT,
      name: 'api-retry',
      workflowType: 'requirement',
    });
    await waitFor(() => expect(result.current.records).toEqual([promoted]));
    expect(result.current.records[0].promotedTo).toBe('chg-018f3a-0001');
  });

  it('updateTitle / promote reject：error 置位（清单保持原值）且 Promise 拒绝供详情页行内捕获', async () => {
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') return Promise.resolve([record(1, 'api-retry')]);
      if (command === 'update_explore_title') return Promise.reject(new Error('回填失败'));
      if (command === 'promote_explore') return Promise.reject(new Error('启动变更失败'));
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toHaveLength(1));

    await act(async () => {
      await expect(result.current.updateTitle('api-retry', '标题')).rejects.toThrow('回填失败');
    });
    await waitFor(() => expect(result.current.error).toContain('回填失败'));
    expect(result.current.records).toEqual([record(1, 'api-retry')]);

    await act(async () => {
      await expect(result.current.promote('api-retry', 'requirement')).rejects.toThrow(
        '启动变更失败',
      );
    });
    await waitFor(() => expect(result.current.error).toContain('启动变更失败'));
    expect(result.current.records).toEqual([record(1, 'api-retry')]);
  });

  it('无 root 守卫：root 为 null → updateTitle / promote 均 no-op（零 IPC）', async () => {
    const { result } = renderHook(() => useExploreList(null));

    await act(async () => {
      await result.current.updateTitle('topic', '标题');
      await result.current.promote('topic', 'requirement');
    });

    expect(invokeMock).not.toHaveBeenCalled();
  });
});

// ---------------------------------------------------------------------------
// 详情页动作薄封装（desktop-test-only-flow AC-8）：updateWorkflowType(name,
// workflowType) —— invoke 后 refresh；失败落 error 且向外 rethrow 供详情页行内
// 捕获；无 root 守卫为 no-op（零 IPC）。
// ---------------------------------------------------------------------------

describe('useExploreList：updateWorkflowType 动作（回填唯一写口，AC-8）', () => {
  it('updateWorkflowType：invoke("update_explore_workflow_type", { root, name, workflowType }) → 成功后以当前 root 重新取数', async () => {
    const testOnly: ExploreRecord = { ...record(1, 'api-retry'), workflowType: 'test-only' };
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') {
        const updated = invokeMock.mock.calls.some(
          ([name]) => name === 'update_explore_workflow_type',
        );
        return Promise.resolve(updated ? [testOnly] : [record(1, 'api-retry')]);
      }
      if (command === 'update_explore_workflow_type') return Promise.resolve(testOnly);
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toEqual([record(1, 'api-retry')]));
    expect(result.current.records[0].workflowType).toBe('requirement');

    await act(async () => {
      await result.current.updateWorkflowType('api-retry', 'test-only');
    });

    expect(invokeMock).toHaveBeenCalledWith('update_explore_workflow_type', {
      root: ROOT,
      name: 'api-retry',
      workflowType: 'test-only',
    });
    await waitFor(() => expect(result.current.records).toEqual([testOnly]));
    expect(result.current.records[0].workflowType).toBe('test-only');
    expect(invokeMock).toHaveBeenLastCalledWith('list_explore_records', { root: ROOT });
  });

  it('updateWorkflowType 两合法值逐值透传（requirement / test-only 参数逐字不变）', async () => {
    invokeMock.mockResolvedValue([record(1, 'api-retry')]);

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await act(async () => {
      await result.current.updateWorkflowType('api-retry', 'test-only');
    });
    expect(invokeMock).toHaveBeenCalledWith('update_explore_workflow_type', {
      root: ROOT,
      name: 'api-retry',
      workflowType: 'test-only',
    });

    await act(async () => {
      await result.current.updateWorkflowType('api-retry', 'requirement');
    });
    expect(invokeMock).toHaveBeenCalledWith('update_explore_workflow_type', {
      root: ROOT,
      name: 'api-retry',
      workflowType: 'requirement',
    });
    expect(
      invokeMock.mock.calls.filter(([name]) => name === 'update_explore_workflow_type'),
    ).toHaveLength(2);
  });

  it('边界：超长（>1000 字符）与特殊字符（内嵌换行 / NUL / emoji）值零本地校验、逐字透传（权威在后端）', async () => {
    invokeMock.mockResolvedValue([record(1, 'api-retry')]);

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    const edgeValues = ['x'.repeat(1200), 'require\nment', 'test-only\u0000', 'test-only🚀'];
    for (const workflowType of edgeValues) {
      await act(async () => {
        await result.current.updateWorkflowType('api-retry', workflowType);
      });
      expect(invokeMock).toHaveBeenCalledWith('update_explore_workflow_type', {
        root: ROOT,
        name: 'api-retry',
        workflowType,
      });
    }
    expect(
      invokeMock.mock.calls.filter(([name]) => name === 'update_explore_workflow_type'),
    ).toHaveLength(edgeValues.length);
    expect(result.current.error).toBeNull();
  });

  it('updateWorkflowType reject：error 置位（清单保持原值：workflowType 不变）且 Promise 拒绝供行内捕获', async () => {
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_explore_records') return Promise.resolve([record(1, 'api-retry')]);
      if (command === 'update_explore_workflow_type') {
        return Promise.reject(new Error('workflow_type "bug-fix" 不受支持'));
      }
      return Promise.resolve(null);
    });

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.records).toHaveLength(1));

    await act(async () => {
      await expect(result.current.updateWorkflowType('api-retry', 'bug-fix')).rejects.toThrow(
        '不受支持',
      );
    });

    await waitFor(() => expect(result.current.error).toContain('不受支持'));
    expect(result.current.records).toEqual([record(1, 'api-retry')]);
    expect(result.current.records[0].workflowType).toBe('requirement');
  });

  it('无 root 守卫：root 为 null → updateWorkflowType no-op（零 IPC、不入 error 态）', async () => {
    const { result } = renderHook(() => useExploreList(null));

    await act(async () => {
      await result.current.updateWorkflowType('topic', 'test-only');
    });

    expect(invokeMock).not.toHaveBeenCalled();
    expect(result.current.error).toBeNull();
  });

  it('三个详情页动作并列可用（updateTitle / updateWorkflowType / promote 同源薄封装）', async () => {
    invokeMock.mockResolvedValue([record(1, 'api-retry')]);

    const { result } = renderHook(() => useExploreList(ROOT));
    await waitFor(() => expect(result.current.loading).toBe(false));

    await act(async () => {
      await result.current.updateTitle('api-retry', '标题');
      await result.current.updateWorkflowType('api-retry', 'test-only');
      await result.current.promote('api-retry', 'test-only');
    });

    const names = invokeMock.mock.calls
      .map(([name]) => name)
      .filter((name) => name !== 'list_explore_records');
    expect(names).toEqual([
      'update_explore_title',
      'update_explore_workflow_type',
      'promote_explore',
    ]);
  });
});

