import { render, screen, within } from '@testing-library/react';
import { describe, expect, it } from 'vite-plus/test';

import type { ArtifactEnvelope } from '../../../types/dto';
import { EvalChecklistRenderer } from './eval-checklist-renderer';

function envelope(payload: unknown, fallbackText: string | null = null): ArtifactEnvelope {
  return { kind: 'eval-checklist', version: 1, title: '评估清单', payload, fallbackText };
}

const fullPayload = {
  phase: 'proposal',
  attempt: 2,
  verdict: 'pass',
  items: [
    { item: '问题描述清晰', pass: true, evidence: 'L11-23 含痛点与动机' },
    { item: '范围明确', pass: false, evidence: '缺删除清单' },
  ],
};

const validItem = { item: '问题描述清晰', pass: true, evidence: 'L11-23 含痛点与动机' };

/** 断言 payload 被拒收：以保底 <pre> 呈现（fallback-text 挂钩）且未渲染清单区块。 */
function expectFallback(text: string): void {
  expect(screen.getByTestId('fallback-text').textContent).toBe(text);
  expect(screen.queryByTestId('checklist')).toBeNull();
}

describe('EvalChecklistRenderer：items（item / pass / evidence）清单渲染', () => {
  it('items 渲染为清单，每条含 item 名与 evidence', () => {
    render(<EvalChecklistRenderer envelope={envelope(fullPayload)} />);
    expect(screen.getByText('问题描述清晰') !== null).toBe(true);
    expect(screen.getByText('L11-23 含痛点与动机') !== null).toBe(true);
    expect(screen.getByText('范围明确') !== null).toBe(true);
    expect(screen.getByText('缺删除清单') !== null).toBe(true);
  });

  it('pass true / false 条目有可区分的标识文案', () => {
    render(<EvalChecklistRenderer envelope={envelope(fullPayload)} />);
    // 在 checklist 域内收集 checklist-verdict 徽标文本（verdict 徽标在 attempt-meta 域，不入此列）
    const badgeTexts = within(screen.getByTestId('checklist'))
      .getAllByTestId('checklist-verdict')
      .map((badge) => badge.textContent ?? '');
    expect(badgeTexts).toContain('pass');
    expect(badgeTexts).toContain('fail');
  });

  it('items 为空数组时渲染空清单不崩（回退保底文本）', () => {
    render(
      <EvalChecklistRenderer
        envelope={envelope({ ...fullPayload, items: [] }, '- [x] 保底清单文本')}
      />,
    );
    expect(screen.getByText('- [x] 保底清单文本') !== null).toBe(true);
  });

  it('attempt 为 null 时不出现 NaN / undefined 字样', () => {
    const { container } = render(
      <EvalChecklistRenderer envelope={envelope({ ...fullPayload, attempt: null })} />,
    );
    expect(container.textContent).not.toContain('NaN');
    expect(container.textContent).not.toContain('undefined');
    expect(container.textContent).toContain('phase: proposal');
  });

  it('payload 缺 items 字段时不抛错（回退空态）', () => {
    expect(() =>
      render(<EvalChecklistRenderer envelope={envelope({ phase: 'x' })} />),
    ).not.toThrow();
    expect(screen.getByText('（清单为空）') !== null).toBe(true);
  });
});

describe('EvalChecklistRenderer：payload 收窄、统计与降级分支', () => {
  it('通过计数按 pass 条目数统计而非条目总数', () => {
    const { container } = render(<EvalChecklistRenderer envelope={envelope(fullPayload)} />);
    expect(container.textContent).toContain('1/2 通过');
    expect(container.textContent).not.toContain('2/2 通过');
    expect(container.textContent).not.toContain('0/2 通过');
  });

  it('attempt 有值时展示编号，为 null 时整段隐藏', () => {
    const withAttempt = render(<EvalChecklistRenderer envelope={envelope(fullPayload)} />);
    expect(withAttempt.container.textContent).toContain('attempt: 2');

    const without = render(
      <EvalChecklistRenderer envelope={envelope({ ...fullPayload, attempt: null })} />,
    );
    expect(without.container.textContent).not.toContain('attempt:');
  });

  it('verdict 徽标三态：pass / fail / null 不渲染徽标', () => {
    const pass = render(<EvalChecklistRenderer envelope={envelope(fullPayload)} />);
    expect(within(pass.container).getByTestId('attempt-verdict').textContent).toBe('pass');
    pass.unmount();

    const fail = render(
      <EvalChecklistRenderer envelope={envelope({ ...fullPayload, verdict: 'fail' })} />,
    );
    expect(within(fail.container).getByTestId('attempt-verdict').textContent).toBe('fail');
    fail.unmount();

    const none = render(
      <EvalChecklistRenderer envelope={envelope({ ...fullPayload, verdict: null })} />,
    );
    expect(within(none.container).queryByTestId('attempt-verdict')).toBeNull();
  });

  it('条目徽标按 pass / fail 计数且归属域正确', () => {
    const { container } = render(<EvalChecklistRenderer envelope={envelope(fullPayload)} />);
    // verdict(pass) + 第 1 条 item(pass) → 2 个 pass 徽标；第 2 条 item(fail) → 1 个 fail 徽标
    const verdictTexts = [
      ...within(container).getAllByTestId('attempt-verdict'),
      ...within(container).getAllByTestId('checklist-verdict'),
    ].map((badge) => badge.textContent ?? '');
    expect(verdictTexts.filter((text) => text === 'pass')).toHaveLength(2);
    expect(verdictTexts.filter((text) => text === 'fail')).toHaveLength(1);
    // checklist 域内的条目徽标依次为 pass / fail
    const checklistTexts = within(container)
      .getAllByTestId('checklist-verdict')
      .map((badge) => badge.textContent ?? '');
    expect(checklistTexts).toEqual(['pass', 'fail']);
  });

  it('items 为空数组且无保底文本时渲染（清单为空）占位', () => {
    render(<EvalChecklistRenderer envelope={envelope({ ...fullPayload, items: [] })} />);
    expectFallback('（清单为空）');
  });

  it('payload 非对象（null / 原始值）时回退保底形态且不崩溃', () => {
    for (const bad of [null, 'text', 42, true]) {
      const { unmount } = render(<EvalChecklistRenderer envelope={envelope(bad)} />);
      expectFallback('（清单为空）');
      unmount();
    }
  });

  it('phase / attempt / verdict 类型漂移时拒收 payload', () => {
    const cases: unknown[] = [
      { ...fullPayload, phase: 42 },
      { ...fullPayload, attempt: '2' },
      { ...fullPayload, attempt: undefined },
      { ...fullPayload, verdict: 42 },
    ];
    for (const bad of cases) {
      const { unmount } = render(<EvalChecklistRenderer envelope={envelope(bad)} />);
      expectFallback('（清单为空）');
      unmount();
    }
  });

  it('缺失 phase 字段时拒收 payload', () => {
    const noPhase = { attempt: 2, verdict: 'pass', items: fullPayload.items };
    render(<EvalChecklistRenderer envelope={envelope(noPhase)} />);
    expectFallback('（清单为空）');
  });

  it('verdict 与 attempt 为 null 属合法 payload 并正常渲染清单', () => {
    const { container } = render(
      <EvalChecklistRenderer
        envelope={envelope({
          phase: 'implement',
          attempt: null,
          verdict: null,
          items: fullPayload.items,
        })}
      />,
    );
    expect(within(container).getByTestId('checklist') !== null).toBe(true);
    expect(container.textContent).toContain('phase: implement');
    expect(container.textContent).toContain('1/2 通过');
  });

  it('items 非数组时拒收且不崩溃', () => {
    for (const bad of [{}, 'items', 3]) {
      const payload = { phase: 'proposal', attempt: 1, verdict: 'pass', items: bad };
      const { unmount } = render(<EvalChecklistRenderer envelope={envelope(payload)} />);
      expectFallback('（清单为空）');
      unmount();
    }
  });

  it('items 含非法条目（item / pass / evidence 类型漂移或非对象）时整批拒收', () => {
    const invalidEntries: unknown[] = [
      { item: 42, pass: true, evidence: 'ok' },
      { item: 'x', pass: 'yes', evidence: 'ok' },
      { item: 'x', pass: true, evidence: 42 },
      { item: 'x', pass: true },
      null,
      'entry',
    ];
    for (const bad of invalidEntries) {
      const payload = { phase: 'proposal', attempt: 1, verdict: 'pass', items: [validItem, bad] };
      const { unmount } = render(<EvalChecklistRenderer envelope={envelope(payload)} />);
      expectFallback('（清单为空）');
      unmount();
    }
  });
});

src/views/changes/agent/hooks/use-change.source:
import { act, renderHook, waitFor } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import type {
  AgentEvent,
  AgentPermissionMode,
  SessionPage,
  SessionSummary,
  TurnSummary,
} from '../../../../types/dto';
import { useChangeChat, type ChangeChatParams } from './use-change-chat';

// ---------------------------------------------------------------------------
// 进程边界 Mock（Mock策略表）：`@tauri-apps/api/core` 的 invoke 按命令名分派
// （agent_start / agent_stop / session_detail / agent_session_transcript /
// agent_session_watch / list_change_chat_sessions）；Channel 为可编程类，测试
// 直投 `{ ipc: 'record' }` 信封驱动 early-resolve 轮行与收口。useAgentSession /
// @ai-sdk/react / agent-transport 全部真实组合（hook 即链路入口）。
// ---------------------------------------------------------------------------

const { ChannelMock, invokeMock } = vi.hoisted(() => {
  class ChannelMock {
    onmessage: ((message: unknown) => void) | null = null;
    static instances: ChannelMock[] = [];
    constructor() {
      ChannelMock.instances.push(this);
    }
  }
  return { ChannelMock, invokeMock: vi.fn() };
});

vi.mock('@tauri-apps/api/core', () => ({ invoke: invokeMock, Channel: ChannelMock }));

// ---------------------------------------------------------------------------
// fixture（serde camelCase 线格式；时钟不入 mock——updatedAt / createdAt 由
// fixture 显式给定，排序与显示断言取原始数值）
// ---------------------------------------------------------------------------

const ROOT = 'C:\\demo\\alpha';
const CHANGE_ID = 'chg-1';
const WORKTREE = 'C:\\demo\\wt';
const TS = 1_727_000_000_000;

function turn(turnId: number, status: TurnSummary['status'], sessionId: string): TurnSummary {
  return {
    turnId,
    sessionId,
    status,
    startedAt: TS + turnId,
    finishedAt: status === 'running' ? null : TS + turnId + 900,
    numTurns: status === 'running' ? null : 1,
    costUsd: status === 'running' ? null : 0.1,
    durationMs: status === 'running' ? null : 500,
    error: null,
  };
}

function summary(
  turns: TurnSummary[],
  id: string,
  sourceRef: string | null = CHANGE_ID,
): SessionSummary {
  return {
    row: {
      id,
      remoteSessionId: null,
      configSnapshot: null,
      provenance: { source: 'change', sourceRef },
      createdAt: TS,
      updatedAt: TS + 9,
    },
    stats: {
      turnCount: turns.length,
      totalDurationMs: null,
      inputTokens: null,
      outputTokens: null,
    },
    turns,
  };
}

function emptyPage(): SessionPage {
  return { sessions: [], total: 0 };
}

// ---------------------------------------------------------------------------
// 可编程 IPC 应答（按命令名分派）
// ---------------------------------------------------------------------------

/** 清单应答函数（按 args.offset 分派 / 可切 reject）。 */
type ListHandler = (args: { offset: number; limit: number }) => Promise<SessionPage>;

interface IpcState {
  detail: SessionSummary | null | Error;
  transcript: AgentEvent[] | Error;
  /** 订阅命令：deferred = 挂起（用例直投信封）/ resolve / reject */
  watch: 'deferred' | 'resolve' | 'reject';
  start: TurnSummary | Error;
  list: ListHandler;
}

let ipc: IpcState;

const watchResolvers: (() => void)[] = [];

function resetIpc(overrides: Partial<IpcState> = {}): void {
  ipc = {
    detail: null,
    transcript: [],
    watch: 'deferred',
    start: turn(1, 'running', 'ses-1'),
    list: () => Promise.resolve(emptyPage()),
    ...overrides,
  };
  ChannelMock.instances.length = 0;
  watchResolvers.length = 0;
  invokeMock.mockReset();
  invokeMock.mockImplementation((command: string, args: Record<string, unknown> = {}) => {
    if (command === 'session_detail') {
      return ipc.detail instanceof Error ? Promise.reject(ipc.detail) : Promise.resolve(ipc.detail);
    }
    if (command === 'agent_session_transcript') {
      return ipc.transcript instanceof Error
        ? Promise.reject(ipc.transcript)
        : Promise.resolve(ipc.transcript);
    }
    if (command === 'agent_session_watch') {
      if (ipc.watch === 'reject') return Promise.reject(new Error('watch 命令失败'));
      if (ipc.watch === 'resolve') return Promise.resolve(null);
      return new Promise<null>((resolve) => {
        watchResolvers.push(() => resolve(null));
      });
    }
    if (command === 'agent_start') {
      return ipc.start instanceof Error ? Promise.reject(ipc.start) : Promise.resolve(ipc.start);
    }
    if (command === 'list_change_chat_sessions') {
      return ipc.list({
        offset: Number(args['offset']),
        limit: Number(args['limit']),
      });
    }
    return Promise.resolve(null);
  });
}

beforeEach(() => {
  resetIpc();
});

// ---------------------------------------------------------------------------
// 装置
// ---------------------------------------------------------------------------

interface ChannelLike {
  onmessage: ((message: unknown) => void) | null;
}

function lastChannel(): ChannelLike {
  const instance = ChannelMock.instances.at(-1);
  if (!instance) throw new Error('尚未建立流（无 Channel 实例）');
  return instance;
}

function deliverRecord(record: TurnSummary): void {
  act(() => {
    lastChannel().onmessage?.({ ipc: 'record', record });
  });
}

function callsOf(name: string): unknown[][] {
  return invokeMock.mock.calls.filter(([command]) => command === name);
}

function argsOf(name: string, index = -1): Record<string, unknown> {
  const calls = callsOf(name);
  const call = index < 0 ? calls.at(-1) : calls[index];
  if (!call) throw new Error(`${name} 未被调用`);
  return call[1] as Record<string, unknown>;
}

type Params = ChangeChatParams;

function baseParams(overrides: Partial<Params> = {}): Params {
  return {
    root: ROOT,
    changeId: CHANGE_ID,
    worktree: WORKTREE,
    runActive: false,
    archived: false,
    ...overrides,
  };
}

async function mounted(overrides: Partial<Params> = {}) {
  const rendered = renderHook((props: Params) => useChangeChat(props), {
    initialProps: baseParams(overrides),
  });
  await act(async () => {});
  await act(async () => {});
  return rendered;
}

function rerenderWith(
  rerender: (props: Params) => void,
  overrides: Partial<Params>,
): Promise<void> {
  return act(async () => {
    rerender(baseParams(overrides));
  });
}

function sendInput(
  send: (input: { text: string; permissionMode: AgentPermissionMode }) => void,
  text = '首轮提问',
  permissionMode: AgentPermissionMode = 'default',
): void {
  act(() => {
    send({ text, permissionMode });
  });
}

// ---------------------------------------------------------------------------
// 打开即空态：挂载零取数（AC-4 / AC-5）
// ---------------------------------------------------------------------------

describe('useChangeChat：打开即空态', () => {
  it('挂载后 sessionId 为 null、清单空、未展开，且零会话类 invoke', async () => {
    const { result } = await mounted();

    expect(result.current.sessionId).toBeNull();
    expect(result.current.currentSessionId).toBeNull();
    expect(result.current.sessions).toEqual([]);
    expect(result.current.total).toBe(0);
    expect(result.current.listOpen).toBe(false);
    expect(result.current.listLoading).toBe(false);
    expect(result.current.listError).toBeNull();
    expect(invokeMock).not.toHaveBeenCalled();
    expect(callsOf('list_change_chat_sessions')).toHaveLength(0);
    expect(callsOf('session_detail')).toHaveLength(0);
    expect(callsOf('agent_session_transcript')).toHaveLength(0);
  });

  it('空态不自动恢复最近会话：页面重挂后仍为空态（不选中任何会话）', async () => {
    ipc.list = () => Promise.resolve({ sessions: [summary([], 'ses-old')], total: 1 });
    const first = await mounted();
    expect(first.result.current.sessions).toEqual([]);
    expect(first.result.current.sessionId).toBeNull();
    first.unmount();

    const second = await mounted();
    expect(second.result.current.sessionId).toBeNull();
    expect(second.result.current.currentSessionId).toBeNull();
    expect(callsOf('session_detail')).toHaveLength(0);
  });
});

// ---------------------------------------------------------------------------
// 归属与执行根注入（AC-1 / AC-3 / AC-4）
// ---------------------------------------------------------------------------

describe('useChangeChat：归属与执行根注入', () => {
  it('空态首发携 source=change / sourceRef=changeId / cwd=worktree / sessionId=null', async () => {
    const { result } = await mounted();

    sendInput(result.current.send);
    await act(async () => {});

    expect(callsOf('agent_start')).toHaveLength(1);
    expect(argsOf('agent_start')).toMatchObject({
      root: ROOT,
      prompt: '首轮提问',
      sessionId: null,
      source: 'change',
      sourceRef: CHANGE_ID,
      cwd: WORKTREE,
      permissionMode: 'default',
    });
  });

  it('worktree 为 null（legacy）→ cwd 传 null，后端回落 root', async () => {
    const { result } = await mounted({ worktree: null });
    expect(result.current.cwd).toBeNull();

    sendInput(result.current.send);
    await act(async () => {});

    expect(argsOf('agent_start')['cwd']).toBeNull();
  });

  it('归档 change 不传悬空 worktree（cwd 恒 null）', async () => {
    const { result } = await mounted({ archived: true });
    expect(result.current.cwd).toBeNull();

    sendInput(result.current.send);
    await act(async () => {});

    expect(callsOf('agent_start'), '归档只读零发起').toHaveLength(0);
  });
});

// ---------------------------------------------------------------------------
// 禁发判据单源（AC-6 矩阵四行 + 优先级；`sessionId === null` 不入判据）
// ---------------------------------------------------------------------------

describe('useChangeChat：禁发判据单源', () => {
  it('row3：无 run 的 active 且会话未运行 → 理由 null、可发可起（空态同判）', async () => {
    const { result } = await mounted();

    expect(result.current.disabledReason).toBeNull();
    expect(result.current.canSend).toBe(true);
    expect(result.current.canStart).toBe(true);
    expect(result.current.sessionId, '空态即草案态（不单独构成禁用理由）').toBeNull();
  });

