    const graph = buildFlowGraph(detail(), long);
    expect(graph.nodes).toHaveLength(80);
    expect(nodeIds(graph.nodes)).toEqual(nodeIds(long));
    expect(new Set(nodeIds(graph.nodes)).size).toBe(80);
