  it('边界：runNodes 为 undefined / 空数组 → 与缺省同形（零节点零边，不抛错）', () => {
    const base = detail();
    expect(buildFlowGraph(base).nodes).toEqual([]);
    expect(buildFlowGraph(base, []).nodes).toEqual([]);
    expect(buildFlowGraph(base).columns).toHaveLength(REQUIREMENT_PHASES.length);
