  it('backtrack 边 label 取发起相位最近一次条目记因（pipeline 参数保留生效）', () => {
    const base = detail({
      pipeline: REQUIREMENT_PHASES.map((phase) =>
        phase === 'implement'
          ? station(phase, [
              attempt({ attempt: 1 }),
              attempt({ attempt: 2, backtrackTo: 'test-design', backtrackReason: '实现缺陷回改' }),
            ])
